// The trap: indexing a string gives BYTES, ranging gives RUNES. For ASCII
// interview input they coincide; for anything else they do not.
fmt.Println(len("héllo"))          // 6 bytes
fmt.Println(len([]rune("héllo")))  // 5 characters

// Palindrome over runes, two pointers.
func isPalindrome(s string) bool {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		if r[i] != r[j] {
			return false
		}
	}
	return true
}

// Anagram: a 26-slot count beats sorting.
func isAnagram(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	var cnt [26]int
	for i := 0; i < len(a); i++ {
		cnt[a[i]-'a']++
		cnt[b[i]-'a']--
	}
	return cnt == [26]int{} // arrays are comparable in Go
}

