// Go grows goroutine stacks dynamically, so deep recursion is far safer here
// than in Python or C — but it is still not free.
func fib(n int, memo map[int]int) int {
	if n <= 1 {
		return n
	}
	if v, ok := memo[n]; ok {
		return v
	}
	memo[n] = fib(n-1, memo) + fib(n-2, memo)
	return memo[n]
}

// Subsets: at each index, take the element or don't.
func subsets(nums []int) [][]int {
	var out [][]int
	var cur []int

	var go_ func(i int)
	go_ = func(i int) {
		if i == len(nums) {
			// MUST copy: cur's backing array is reused as we backtrack.
			out = append(out, append([]int(nil), cur...))
			return
		}
		go_(i + 1) // skip
		cur = append(cur, nums[i])
		go_(i + 1) // take
		cur = cur[:len(cur)-1]
	}
	go_(0)
	return out
}

backtracking.code:
// choose -> explore -> un-choose.
func permute(nums []int) [][]int {
	var out [][]int
	var cur []int
	used := make([]bool, len(nums))

	var rec func()
	rec = func() {
		if len(cur) == len(nums) {
			out = append(out, append([]int(nil), cur...)) // copy
			return
		}
		for i, x := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			cur = append(cur, x) // choose
			rec()                // explore
			cur = cur[:len(cur)-1]
			used[i] = false // un-choose
		}
	}
	rec()
	return out
}

