// The pattern behind next-greater, largest-rectangle and daily-temperatures.
// Each index is pushed and popped at most once, so O(n) overall.
func nextGreater(a []int) []int {
	res := make([]int, len(a))
	for i := range res {
		res[i] = -1
	}
	var stack []int // indices, values decreasing
	for i, x := range a {
		for len(stack) > 0 && a[stack[len(stack)-1]] < x {
			res[stack[len(stack)-1]] = x
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, i)
	}
	return res
}

// Sliding window maximum with a deque of indices.
func windowMax(a []int, k int) []int {
	var dq []int // indices; a[dq] decreasing
	var out []int
	for i, x := range a {
		for len(dq) > 0 && dq[0] <= i-k {
			dq = dq[1:] // left the window
		}
		for len(dq) > 0 && a[dq[len(dq)-1]] <= x {
			dq = dq[:len(dq)-1] // dominated, can never be the max
		}
		dq = append(dq, i)
		if i >= k-1 {
			out = append(out, a[dq[0]])
		}
	}
	return out
}

