// BST invariant: everything left < node < everything right, against INHERITED
// bounds. Comparing only against the parent is the classic wrong answer and
// it passes small tests.
func isValid(root *TreeNode, lo, hi *int) bool {
	if root == nil {
		return true
	}
	if lo != nil && root.Val <= *lo {
		return false
	}
	if hi != nil && root.Val >= *hi {
		return false
	}
	return isValid(root.Left, lo, &root.Val) && isValid(root.Right, &root.Val, hi)
}

func insert(root *TreeNode, v int) *TreeNode {
	if root == nil {
		return &TreeNode{Val: v}
	}
	if v < root.Val {
		root.Left = insert(root.Left, v)
	} else if v > root.Val {
		root.Right = insert(root.Right, v)
	}
	return root
}

// LCA in a BST: the first node that splits the two values.
func lca(root *TreeNode, p, q int) *TreeNode {
	for root != nil {
		switch {
		case p < root.Val && q < root.Val:
			root = root.Left
		case p > root.Val && q > root.Val:
			root = root.Right
		default:
			return root
		}
	}
	return nil
}

heaps.code:
// Go has no ready-made priority queue: container/heap gives you the algorithms
// and you supply the storage by implementing heap.Interface.
type IntHeap []int

func (h IntHeap) Len() int            { return len(h) }
func (h IntHeap) Less(i, j int) bool  { return h[i] < h[j] } // min-heap; flip for max
func (h IntHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)         { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Note Push/Pop are the storage hooks — you call heap.Push/heap.Pop, never
// these directly, or the heap invariant is not maintained.
func kthLargest(nums []int, k int) int {
	h := &IntHeap{}
	heap.Init(h)
	for _, x := range nums {
		heap.Push(h, x)
		if h.Len() > k {
			heap.Pop(h) // evict the smallest
		}
	}
	return (*h)[0]
}

