// Adjacency list as a slice of slices.
adj := make([][]int, n)
adj[u] = append(adj[u], v)

// BFS gives shortest path in an UNWEIGHTED graph. Mark distance on ENQUEUE,
// not on dequeue, or nodes get queued repeatedly.
func bfs(adj [][]int, src int) []int {
	dist := make([]int, len(adj))
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0
	q := []int{src}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if dist[v] == -1 {
				dist[v] = dist[u] + 1
				q = append(q, v)
			}
		}
	}
	return dist
}

// Kahn's topological sort. Fewer than n nodes out means there is a cycle.
func topoSort(adj [][]int) []int {
	n := len(adj)
	indeg := make([]int, n)
	for u := 0; u < n; u++ {
		for _, v := range adj[u] {
			indeg[v]++
		}
	}
	var q []int
	for i := 0; i < n; i++ {
		if indeg[i] == 0 {
			q = append(q, i)
		}
	}
	var order []int
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		order = append(order, u)
		for _, v := range adj[u] {
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	if len(order) != n {
		return nil // cycle
	}
	return order
}

dynamic-programming.code:
// 1. Top-down with a memo map (or slice, when the state is a small int).
func robMemo(a []int, i int, memo []int) int {
	if i >= len(a) {
		return 0
	}
	if memo[i] != -1 {
		return memo[i]
	}
	memo[i] = max(a[i]+robMemo(a, i+2, memo), robMemo(a, i+1, memo))
	return memo[i]
}

// 2. Bottom-up table.
func robTab(a []int) int {
	n := len(a)
	dp := make([]int, n+2)
	for i := n - 1; i >= 0; i-- {
		dp[i] = max(a[i]+dp[i+2], dp[i+1])
	}
	return dp[0]
}

// 3. Rolling — only two states are ever read.
func rob(a []int) int {
	take, skip := 0, 0
	for i := len(a) - 1; i >= 0; i-- {
		take, skip = max(a[i]+skip, take), take
	}
	return take
}

// 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used once;
// upward silently becomes the unbounded version.
func knapsack(wt, val []int, cap int) int {
	dp := make([]int, cap+1)
	for i := range wt {
		for w := cap; w >= wt[i]; w-- {
			dp[w] = max(dp[w], val[i]+dp[w-wt[i]])
		}
	}
	return dp[cap]
}

