// A trie trades memory for prefix queries in O(len), independent of how many
// words are stored.
type Trie struct {
	children [26]*Trie
	end      bool
}

func NewTrie() *Trie { return &Trie{} }

func (t *Trie) Insert(word string) {
	cur := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a'
		if cur.children[c] == nil {
			cur.children[c] = &Trie{}
		}
		cur = cur.children[c]
	}
	cur.end = true
}

func (t *Trie) walk(s string) *Trie {
	cur := t
	for i := 0; i < len(s); i++ {
		cur = cur.children[s[i]-'a']
		if cur == nil {
			return nil
		}
	}
	return cur
}

func (t *Trie) Search(word string) bool {
	n := t.walk(word)
	return n != nil && n.end
}

func (t *Trie) StartsWith(prefix string) bool { return t.walk(prefix) != nil }

